create table dm_private.ai_draft_requests(
  id uuid primary key default gen_random_uuid(),created_by uuid not null references auth.users(id),exam text not null check(exam in('uceed','nid','nift','ceed')),topic text not null,question_type text not null check(question_type in('MCQ','MSQ','NAT','DESCRIPTIVE')),instruction text not null check(char_length(instruction) between 10 and 2000),basis_external_keys text[] not null default '{}',status text not null default 'queued' check(status in('queued','running','succeeded','failed')),model text,response_id text,error text,draft_id uuid references dm_private.question_drafts(id),created_at timestamptz not null default now(),completed_at timestamptz,check(cardinality(basis_external_keys) between 1 and 10)
);
alter table dm_private.ai_draft_requests enable row level security;
revoke all on dm_private.ai_draft_requests from anon,authenticated;
create or replace function public.admin_create_ai_draft_request(p_exam text,p_topic text,p_question_type text,p_instruction text,p_basis_external_keys text[]) returns uuid language plpgsql security definer set search_path=pg_catalog,public,dm_private as $$declare v uuid;begin if not public.is_dmocks_admin()then raise exception'Admin access required';end if;if cardinality(p_basis_external_keys)not between 1 and 10 then raise exception'Choose 1 to 10 basis questions';end if;if exists(select 1 from unnest(p_basis_external_keys)k where not exists(select 1 from dm_private.bank_questions q where q.external_key=k and q.active and q.owner_approved))then raise exception'Basis question is unavailable or not rights-approved';end if;insert into dm_private.ai_draft_requests(created_by,exam,topic,question_type,instruction,basis_external_keys,status)values(auth.uid(),p_exam,trim(p_topic),p_question_type,trim(p_instruction),p_basis_external_keys,'running')returning id into v;return v;end$$;
create or replace function public.admin_ai_draft_basis(p_request_id uuid)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,dm_private as $$declare v jsonb;begin if not public.is_dmocks_admin()then raise exception'Admin access required';end if;select jsonb_build_object('requestId',r.id,'exam',r.exam,'topic',r.topic,'questionType',r.question_type,'instruction',r.instruction,'basis',coalesce((select jsonb_agg(jsonb_build_object('externalKey',q.external_key,'type',q.question_type,'topic',q.topic,'payload',q.payload)order by array_position(r.basis_external_keys,q.external_key))from dm_private.bank_questions q where q.external_key=any(r.basis_external_keys)and q.active and q.owner_approved),'[]'))into v from dm_private.ai_draft_requests r where r.id=p_request_id and r.created_by=auth.uid() and r.status='running';if v is null then raise exception'AI draft request unavailable';end if;return v;end$$;
create or replace function public.complete_ai_draft_request(p_request_id uuid,p_model text,p_response_id text,p_payload jsonb)returns uuid language plpgsql security definer set search_path=pg_catalog,dm_private as $$declare r dm_private.ai_draft_requests;v uuid;begin if auth.role()is distinct from'service_role'then raise exception'Forbidden';end if;select*into r from dm_private.ai_draft_requests where id=p_request_id and status='running'for update;if r.id is null then raise exception'AI draft request unavailable';end if;if jsonb_typeof(p_payload)<>'object'or p_payload->'holds'is distinct from'["ai-generated-human-review"]'::jsonb or p_payload->>'type'is distinct from r.question_type or p_payload->>'topic'is distinct from r.topic or p_payload->>'licence'is distinct from'original-ai-draft'or p_payload->>'sourceKind'is distinct from'generated'or p_payload->'provenance'->'basisExternalKeys'is distinct from to_jsonb(r.basis_external_keys)or length(trim(p_payload->>'prompt'))<10 or length(trim(p_payload->>'explanation'))<5 then raise exception'Unsafe AI draft payload';end if;insert into dm_private.question_drafts(created_by,source_type,source_name,payload)values(r.created_by,'ai','AI request '||r.id,p_payload)returning id into v;update dm_private.ai_draft_requests set status='succeeded',model=p_model,response_id=p_response_id,draft_id=v,completed_at=now()where id=r.id;return v;end$$;
create or replace function public.fail_ai_draft_request(p_request_id uuid,p_model text,p_error text)returns void language plpgsql security definer set search_path=pg_catalog,dm_private as $$begin if auth.role()is distinct from'service_role'then raise exception'Forbidden';end if;update dm_private.ai_draft_requests set status='failed',model=p_model,error=left(p_error,1000),completed_at=now()where id=p_request_id and status='running';end$$;
create or replace function public.admin_ai_draft_requests()returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,dm_private as $$begin if not public.is_dmocks_admin()then raise exception'Admin access required';end if;return(select coalesce(jsonb_agg(jsonb_build_object('id',id,'exam',exam,'topic',topic,'questionType',question_type,'basisExternalKeys',basis_external_keys,'status',status,'model',model,'responseId',response_id,'error',error,'draftId',draft_id,'createdAt',created_at)order by created_at desc),'[]')from dm_private.ai_draft_requests);end$$;
revoke all on function public.admin_create_ai_draft_request(text,text,text,text,text[]),public.admin_ai_draft_basis(uuid),public.admin_ai_draft_requests()from public,anon;
grant execute on function public.admin_create_ai_draft_request(text,text,text,text,text[]),public.admin_ai_draft_basis(uuid),public.admin_ai_draft_requests()to authenticated;
revoke all on function public.complete_ai_draft_request(uuid,text,text,jsonb),public.fail_ai_draft_request(uuid,text,text)from public,anon,authenticated;
grant execute on function public.complete_ai_draft_request(uuid,text,text,jsonb),public.fail_ai_draft_request(uuid,text,text)to service_role;
